def flatten_list(nested_list):
    """
    Flatten a given nested list structure.
    :param nested_list: A list that may contain nested lists.
    :return: A flattened list.
    """
    from collections import Iterable
    from collections.abc import Iterable

    def is_instance(obj):
        """
        Check if an object is an instance of a certain class.
        """
        return isinstance(obj, Iterable)

    def flatten(items, depth=0):
        """
        Recursively flatten the nested list.
        """
        depth += 1
        for i, item in enumerate(items):
            if isinstance(item, list) and len(item) > 0:
                yield from flatten(item, depth+1)
            else:
                yield item

    if not is_instance(nested_list):
        raise ValueError("Input must be a list")

    if not all(isinstance(item, list) for item in nested_list):
        raise ValueError("All elements in the list must be lists")

    flat_list = []
    for item in nested_list:
        for sub_item in item:
            if isinstance(sub_item, list):
                flat_list.extend(sub_item)
            else:
                flat_list.append(sub_item)

    return list(flat_list)

    # Print the first 10 items of the flattened list
    result = []
    for i, item in enumerate(flat_list, 1):
        if i <= 10:
            result.append(str(item))
        else:
            break

    return result

