        return numbers[0]

    if len(numbers) == 2:
        return (numbers[0] + numbers[1]) / 2

    if len(numbers) == 3:
        if numbers[0] == numbers[1]:
            return numbers[1]
        if numbers[1] == numbers[2]:
            return numbers[1]
        if numbers[0] == numbers[1] and numbers[1] == numbers[2]:
            return numbers[2]

    if len(numbers) > 3:
        raise ValueError("More than 3 numbers provided")

    median = numbers[1]
    return float(median)

